"""Farm calculations, shared by the farm programs."""
import math


def bags_needed(kg, bag_size=90):
    """Bags needed for kg of maize. A part-full bag still needs a bag."""
    return math.ceil(kg / bag_size)


def sale_value(kg, price_per_kg):
    """What the harvest sells for."""
    return kg * price_per_kg

