import math


def litres_to_buckets(litres, bucket=20):
    return math.ceil(litres / bucket)


def days_left(level, daily_use):
    if daily_use <= 0:
        raise ValueError("daily use must be more than 0")
    return level // daily_use


if __name__ == "__main__":
    print(f"Demo: 100 litres is {litres_to_buckets(100)} buckets")

