def new_bag():
    return {}


def add(bag, item, qty):
    if qty <= 0:
        raise ValueError("quantity must be more than 0")
    bag[item] = bag.get(item, 0) + qty


def remove(bag, item, qty):
    have = bag.get(item, 0)
    if qty > have:
        raise ValueError(f"only {have} {item} in the bag")
    if qty == have:
        del bag[item]
    else:
        bag[item] = have - qty


def describe(bag):
    if not bag:
        return "empty"
    return ", ".join(f"{name} x{qty}" for name, qty in sorted(bag.items()))

